private static boolean isTrustedNumberType(Class<?> c) {
  // Note: Do not consider LazilyParsedNumber trusted because it could contain
  // an arbitrary malformed string
  return c == Integer.class || c == Long.class || c == Double.class || c == Float.class
      || c == Byte.class || c == Short.class
      || c == BigDecimal.class || c == BigInteger.class
      || c == AtomicInteger.class || c == AtomicLong.class;
}

